.offline-content{width:100%;height:100%;background-repeat:no-repeat;background-position:center;background-size:100% 100%;transform-origin:center;position:absolute;inset:0}
.offline-controls{position:absolute;z-index:500;top:10px;left:10px;display:flex;flex-direction:column;gap:2px}
.offline-controls button{background:#0e324c;color:white;border:1px solid #416883;width:34px;height:34px;font-size:19px;cursor:pointer;border-radius:4px}
.offline-caption{position:absolute;z-index:400;bottom:8px;left:8px;right:8px;background:#082238dc;padding:7px 9px;color:#e2f5ff;font-size:11px;border-radius:6px;pointer-events:none}
.offline-content .pin{z-index:10;cursor:pointer}

/* Squad ADS - Mapa geográfico 2.0 */
.map-primary{height:490px!important;min-height:400px;border:1px solid #315a76;border-radius:15px;overflow:hidden}
.map-map-head,.map-bottom-note{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:7px 0 10px;color:#d4e8f7;font-size:12px}
.map-map-head small,.map-bottom-note{color:#88aabf;font-size:11px}
.map-filter-ribbon{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:14px 0 8px}
.filter-caption{font-size:10px;letter-spacing:1.4px;font-weight:800;color:#6cabc8;margin-right:6px}
.map-filter,.map-reset{color:#bcd5e7;background:#12283c;border:1px solid #345169;border-radius:30px;padding:8px 12px;font-size:12px;transition:.15s}
.map-filter:hover,.map-reset:hover,.map-filter.active{border-color:#43c6ef;color:#fff;background:#154668}
.map-filter.active{box-shadow:inset 0 0 0 1px #43c6ef44}
.map-filter b{color:#5bdbff;font-size:10px;margin-left:5px}
.status-bullet{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px;vertical-align:middle}
.status-bullet.ok{background:#38da94}.status-bullet.caution{background:#edbd57}.status-bullet.error{background:#f26679}
.map-reset{margin-left:auto}
.cluster-marker{width:42px;height:42px;display:grid;place-items:center;background:#163e58e8;border:3px solid #4dccfa;border-radius:50%;color:white;font-size:14px;font-weight:800;box-shadow:0 0 0 7px #38bdf833,0 7px 20px #051321aa}
.cluster-marker span{pointer-events:none}
.map-primary.map-expanded{position:fixed!important;inset:16px!important;width:calc(100vw - 32px)!important;height:calc(100vh - 32px)!important;z-index:9999!important;border:2px solid #43c6ef;box-shadow:0 0 0 900px #030b17df,0 18px 55px #0009}
.map-fullscreen-close{position:fixed;z-index:10001;right:32px;top:30px;border:1px solid #62c8ee;background:#102e46;color:#fff;border-radius:9px;padding:11px 15px;cursor:pointer}
.city-map .leaflet-popup-content a{color:#81ddff}
@media(max-width:720px){.map-primary{height:420px!important;min-height:330px}.map-reset{margin-left:0}.map-filter-ribbon{gap:6px}.map-filter{padding:7px 9px}.map-map-head small{display:block}}

/* =================== REFINAMENTO VISUAL SQUAD ADS ===================
   Paleta original: azul-marinho, ciano, dourado e cores semânticas. */
:root{--squad-cyan:#43c6ef;--squad-blue:#2e91ce;--squad-gold:#e5b449;--squad-ink:#071522;--squad-line:rgba(100,170,215,.18)}
.section.active{animation:sectionEnter .35s ease both}
@keyframes sectionEnter{from{opacity:.55;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
.panel,.card,.activity-card,.solar-card,.feature-card{border:1px solid var(--squad-line)!important;box-shadow:0 6px 28px rgba(0,8,20,.18);transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease}
.panel:hover,.card:hover{box-shadow:0 12px 36px rgba(0,8,20,.25);border-color:rgba(67,198,239,.32)!important}
.btn,.nav,.quick,.map-filter,.period-btn{transition:background .2s,transform .18s,color .2s,box-shadow .2s}
.btn:not(:disabled):hover,.period-btn:hover{transform:translateY(-2px)}
:focus-visible{outline:3px solid var(--squad-cyan)!important;outline-offset:3px!important}
.nav.active{box-shadow:inset 3px 0 0 var(--squad-cyan),0 4px 16px rgba(0,10,23,.2);font-weight:750}
.status{font-weight:750!important;letter-spacing:.01em}
.status.atencao{color:#f7cd6c!important}
.map .leaflet-container{background:#0a1726}
.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:#11293c;color:#e8f5fc;border:1px solid #28516a}
.leaflet-popup-content{line-height:1.7}
.leaflet-popup-content a{color:#58d0f7}
.leaflet-bar a{background:#102d43;color:#ecf9ff;border-color:#31526c}
.leaflet-bar a:hover{background:#1e526c;color:#fff}
.post-marker.falha{animation:postPulse 1.8s ease-out infinite;box-shadow:0 0 0 0 rgba(255,86,99,.65)}
@keyframes postPulse{0%{box-shadow:0 0 0 0 rgba(255,86,99,.6)}65%{box-shadow:0 0 0 13px rgba(255,86,99,0)}100%{box-shadow:0 0 0 0 rgba(255,86,99,0)}}
.map-failure-note{position:absolute;z-index:450;bottom:24px;left:12px;right:12px;max-width:470px;margin:auto;background:rgba(12,35,52,.94);border:1px solid #36718e;border-radius:12px;padding:11px 14px;color:#e8f7fd;box-shadow:0 8px 25px #0009;text-align:center;pointer-events:none;font-size:12px}
.section-intro,.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:16px}
.section-intro h2{font-size:clamp(22px,2.6vw,32px);margin:5px 0}
.period-tabs{display:inline-flex;gap:5px;background:rgba(3,18,31,.7);padding:5px;border:1px solid var(--squad-line);border-radius:12px}
.period-btn{border:0;background:transparent;color:#adccdc;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}
.period-btn.active{background:linear-gradient(135deg,#155984,#1b81aa);color:white;box-shadow:0 2px 12px #0d90d155}
.energy-kpis{grid-template-columns:repeat(5,minmax(0,1fr))!important}
.energy-kpis .card{min-width:0;padding:20px!important}
.energy-kpis .number{font-size:clamp(18px,2vw,26px)!important}
.energy-kpis .card small{display:block;margin-top:8px}
.energy-kpis .kpi-up{color:#6ce1a2}.energy-kpis .kpi-down{color:#f0bd5a}
.energy-kpis .card:nth-child(1){border-top:2px solid var(--squad-gold)!important}
.energy-kpis .card:nth-child(2){border-top:2px solid var(--squad-blue)!important}
.energy-kpis .card:nth-child(3){border-top:2px solid var(--squad-cyan)!important}
.energy-kpis .card:nth-child(4){border-top:2px solid #93add0!important}
.tiny-label{font-size:10px;letter-spacing:.1em;color:#95aec1;border:1px solid #31516a;padding:7px 10px;border-radius:99px;font-weight:800}
.graph-container{position:relative;width:100%;min-width:0}
.graph-main{height:310px}.graph-dashboard{height:235px}.graph-donut{height:220px}.graph-battery{height:250px}
.graph-container canvas{display:block;width:100%!important;height:100%!important}
.energy-secondary{display:grid;grid-template-columns:1fr 1.3fr;gap:14px;margin:14px 0}
.origin-legend{display:flex;flex-wrap:wrap;gap:7px 17px;justify-content:center;color:#bcd6e5;font-size:12px;margin:6px 0}
.origin-key{display:inline-flex;align-items:center;gap:6px}.origin-key i{height:9px;width:9px;display:inline-block;border-radius:50%}
.energy-note{margin-top:12px}
.energy-info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.energy-info-grid>div{background:rgba(38,79,108,.25);border:1px solid var(--squad-line);border-radius:12px;padding:14px;display:grid;gap:6px}
.energy-info-grid b{color:#e5f7ff;font-size:13px}.energy-info-grid span{color:#9ebcd1;font-size:12px;line-height:1.6}
.lighting-overview,.report-overview,.alert-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:17px 0}
.insight-tile{background:linear-gradient(145deg,rgba(17,54,81,.76),rgba(8,29,47,.58));border:1px solid var(--squad-line);border-radius:13px;padding:16px}
.insight-tile .label{font-size:12px;color:#abcadd}.insight-tile strong{font-size:21px;display:block;margin-top:8px;color:#edf9ff}
.insight-tile small{font-size:11px;display:block;margin-top:5px;color:#89aec4}
.row-focus{cursor:pointer}.row-focus:hover{background:rgba(44,143,199,.14)}
@media(max-width:1200px){.energy-kpis{grid-template-columns:repeat(3,minmax(0,1fr))!important}}
@media(max-width:820px){.energy-kpis{grid-template-columns:repeat(2,minmax(0,1fr))!important}.energy-secondary{grid-template-columns:1fr}.energy-info-grid{grid-template-columns:1fr}}
@media(max-width:540px){.energy-kpis,.lighting-overview,.report-overview,.alert-overview{grid-template-columns:1fr 1fr!important}.period-tabs{width:100%;justify-content:space-between}.period-btn{flex:1;padding:10px 4px}.graph-main{height:250px}.graph-dashboard{height:210px}}
@media print{.sidebar,.period-tabs,.actions,.btn{display:none!important}.section{display:block!important;break-inside:avoid}.graph-container{break-inside:avoid}}


/* =================== ESTILO DO MAPA VETORIAL ===================
   Azul e ciano Squad ADS; controle, popup, agrupamento e foco no teclado. */
.city-map,.map-primary{position:relative;background:#0c2032!important}
.city-map .maplibregl-canvas{outline:none}
.city-map .maplibregl-control-container{font-family:Inter,system-ui,Arial,sans-serif}
.city-map .maplibregl-ctrl-group{background:#103049;border:1px solid #3b6b88;box-shadow:0 6px 20px #0004}
.city-map .maplibregl-ctrl button{filter:invert(.8) sepia(.1) hue-rotate(165deg)}
.city-map .maplibregl-ctrl-attrib{background:#0c2236e8;color:#a1d7f5;font-size:10px}
.city-map .maplibregl-ctrl-attrib a{color:#6bcffa}
.squad-gl-marker,.squad-gl-cluster{border:0;display:grid;place-items:center;cursor:pointer;touch-action:manipulation}
.squad-gl-marker{width:24px;height:24px;border-radius:50%;background:#102b40d9}
.squad-gl-marker-core{display:block;width:14px;height:14px;border-radius:50%;background:#1cd481;border:2px solid #e9fff4;box-shadow:0 0 0 4px #00cd6f45,0 0 12px #1cd48180}
.squad-gl-marker.atencao .squad-gl-marker-core{background:#f5cb3c;box-shadow:0 0 0 4px #ffc43a55}
.squad-gl-marker.falha .squad-gl-marker-core{background:#fa5367;box-shadow:0 0 0 4px #ed394c55;animation:squadMapPulse 1.8s ease-out infinite}
.squad-gl-cluster{width:39px;height:39px;border-radius:50%;color:#fff;font-size:13px;font-weight:800;background:#146b9b;border:3px solid #80e0ff;box-shadow:0 0 0 5px #15649b55,0 8px 18px #0008}
.squad-gl-search-pin{width:20px;height:20px;border:4px solid #b5f2ff;border-radius:50%;background:#1ba8ef;box-shadow:0 0 0 8px #16b8fc4b}
.city-map .maplibregl-popup-content{background:#102c43;color:#ecf8ff;border:1px solid #3b6988;border-radius:14px;padding:13px;box-shadow:0 14px 30px #0008}
.city-map .maplibregl-popup-tip{border-top-color:#102c43;border-bottom-color:#102c43}
.city-map .maplibregl-popup-close-button{color:#fff;font-size:19px}
.squad-gl-popup{line-height:1.5;display:grid;gap:4px;min-width:190px}
.squad-gl-popup small{color:#9fc3d7}
.squad-map-notice{z-index:8!important;pointer-events:auto;display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap}
.squad-gl-marker:focus-visible,.squad-gl-cluster:focus-visible,.city-map button:focus-visible{outline:3px solid #72d9ff;outline-offset:4px}
@keyframes squadMapPulse{50%{box-shadow:0 0 0 10px #f5475700,0 0 19px #f54757}}
@media(prefers-reduced-motion:reduce){.squad-gl-marker-core{animation:none!important}}
.squad-offline-label{position:absolute;z-index:5;bottom:10px;left:10px;right:10px;max-width:540px;margin:auto;pointer-events:none;
 background:#0b2639e8;color:#dceefa;font-size:11px;text-align:center;padding:9px 12px;border:1px solid #3d7290;border-radius:10px}
.squad-offline-label button{pointer-events:auto;margin-left:10px;margin-top:4px}
.squad-street-label{pointer-events:none;color:#d3ebf6;text-shadow:0 1px 4px #07131b,0 0 6px #08131b;font-size:11px;font-weight:700;
 white-space:nowrap;opacity:.84;background:#10334b99;padding:2px 4px;border-radius:4px}
body:has(.map-expanded) .squad-offline-label{max-width:600px}

/* === IBGE: controles e contorno do município, mantendo a identidade Squad ADS === */
.squad-ibge-control{background:rgba(8,30,49,.94);border:1px solid #3a7b9c;border-radius:9px;padding:5px 8px;color:#d7f3ff;box-shadow:0 6px 22px #0007;display:flex;flex-direction:column;gap:4px;max-width:210px;font:600 11px/1.4 system-ui,sans-serif}
.squad-ibge-control button{appearance:none;border:1px solid #28799d;background:#104361;color:#e6faff;border-radius:6px;padding:6px 8px;cursor:pointer;text-align:left;font-size:11px}
.squad-ibge-control button:hover{background:#175a7b}
.squad-ibge-control button:focus-visible{outline:2px solid #52d5ff;outline-offset:2px}
.squad-ibge-state{font-weight:400;font-size:10px;color:#bad5e4;max-width:185px;overflow-wrap:anywhere}
.leaflet-container .squad-ibge-control{pointer-events:auto}


/* Ajustes Leaflet para os cards escuros Squad ADS. */
.leaflet-container{background:#0b2134!important;font-family:inherit;z-index:0}
.leaflet-control-attribution{font-size:10px!important}
.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:#10283d;color:#e9f7ff}
.leaflet-popup-content{font-family:inherit;line-height:1.6}
.leaflet-popup-content p{margin:6px 0}
.leaflet-control-zoom a{background:#12354e;color:#ddf6ff;border-color:#345b76}
.squad-leaflet-icon,.squad-leaflet-cluster{border:0;background:transparent}
.squad-post-dot{display:block;width:17px;height:17px;margin:4px;border-radius:50%;background:#1ad887;border:2px solid #e9fff4;box-shadow:0 0 0 4px #06ba764f,0 0 12px #24ce83}
.squad-post-dot.atencao{background:#f4c23e;border-color:#fff0b2;box-shadow:0 0 0 4px #efc54d51,0 0 12px #ffca56}
.squad-post-dot.falha{background:#f06575;border-color:#ffe2e6;box-shadow:0 0 0 4px #ed566451,0 0 13px #ff5f77;animation:squad-leaflet-pulse 1.8s ease-in-out infinite}
@keyframes squad-leaflet-pulse{50%{box-shadow:0 0 0 10px #ed56641e,0 0 21px #ff5f77}}
.squad-cluster-bubble{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;font-weight:800;color:white;background:#087cb4;border:2px solid #acefff;box-shadow:0 0 0 6px #158ad846}
.squad-map-notice{z-index:800;pointer-events:auto}
.squad-map-notice button{margin-top:7px}
